import torch
import torch.nn as nn
from torch.distributions import Categorical

class Policy(nn.Module):
    def __init__(self, state_dim, action_dim):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(state_dim, 64), nn.Tanh(), nn.Linear(64, action_dim))

    def distribution(self, state):
        logits = self.net(state)
        return Categorical(logits=logits)

    def act(self, state):
        dist = self.distribution(state)
        action = dist.sample()
        return action.item(), dist.log_prob(action)

policy = Policy(state_dim=4, action_dim=2)
optimizer = torch.optim.Adam(policy.parameters(), lr=1e-3)
state = torch.zeros(4)
action, log_prob = policy.act(state)
print(action, log_prob.item())

def discounted_returns(rewards, gamma):
    result = []
    running = 0.0
    for reward in reversed(rewards):
        running = reward + gamma * running
        result.append(running)
    return list(reversed(result))

def reinforce_update(policy, optimizer, log_probs, rewards, gamma=0.99):
    returns = discounted_returns(rewards, gamma)
    returns = torch.tensor(returns, dtype=torch.float32)
    if len(returns) > 1:
        returns = (returns - returns.mean()) / (returns.std(unbiased=False) + 1e-8)
    log_probs = torch.stack(log_probs)
    loss = -(log_probs * returns).sum()
    optimizer.zero_grad()
    loss.backward()
    torch.nn.utils.clip_grad_norm_(policy.parameters(), 1.0)
    optimizer.step()
    return loss.item()
